export const inlineAccent = cva("", {
  variants: {
    status: {
      default: "text-foreground",
      info: "text-fp-banner-accent-info",
      caution: "text-fp-banner-accent-caution",
      warning: "text-fp-banner-accent-warning",
      success: "text-fp-banner-accent-success",
    },
  },
  defaultVariants: { status: "default" },
});

export interface BannerInlineProps
  extends Omit<React.ComponentProps<"div">, "children" | "title">,
    VariantProps<typeof inlineAccent> {
  children: React.ReactNode;
  /**
   * A heading over the message, in the status colour.
   *
   * WITHOUT IT THE BANNER IS ONE 32px LINE, which is the shape it was built
   * for and the shape most alerts want. Some say a thing and then say what
   * follows from it — a state and its consequence — and squeezing both into one
   * truncating line lost the half that mattered. With a title the banner grows
   * to fit and stops truncating; the message drops to muted so the two lines
   * are a heading and a body rather than two sentences of equal weight.
   */
  title?: React.ReactNode;
  /**
   * Title and message on ONE line, at opposite ends of it.
   *
   * A STATE AND ITS CONSEQUENCE ARE NOT A HEADING AND A BODY when the
   * consequence is four words long. Stacked, the pair takes 48px and the
   * second line reads as something further to do; split, it is one 32px line
   * that says the state on the left and what follows from it on the right,
   * which is how anyone would say it out loud. Use it when the message is
   * short and fixed; leave it off when the message can run on, because at the
   * right-hand end there is nowhere for it to run.
   */
  split?: boolean;
  onDismiss?: () => void;
  icon?: React.ReactNode;
}

function BannerInline({
  status = "default",
  className,
  children,
  title,
  split = false,
  onDismiss,
  icon,
  ...props
}: BannerInlineProps) {
  const stacked = Boolean(title) && !split;
  return (
    <div
      role="status"
      data-status={status}
      className={cn(
        "flex gap-2 rounded-md bg-fp-card-1 px-3",
        stacked ? "items-start py-2.5" : "h-8 items-center",
        className
      )}
      {...props}
    >
      <span
        className={cn(
          "shrink-0 [&_svg]:size-4",
          stacked && "mt-px",
          inlineAccent({ status })
        )}
      >
        {icon ?? <Info />}
      </span>
      {title && split ? (
        <span className="flex min-w-0 flex-1 items-baseline justify-between gap-4">
          <span
            className={cn(
              "shrink-0 text-sm font-medium",
              inlineAccent({ status })
            )}
          >
            {title}
          </span>
          <span className="truncate text-xs text-muted-foreground">
            {children}
          </span>
        </span>
      ) : stacked ? (
        <span className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span className={cn("text-sm font-medium", inlineAccent({ status }))}>
            {title}
          </span>
          <span className="text-xs text-muted-foreground">{children}</span>
        </span>
      ) : (
        <span className={cn("flex-1 truncate text-sm", inlineAccent({ status }))}>
          {children}
        </span>
      )}
      {onDismiss && (
        <button
          type="button"
          onClick={onDismiss}
          aria-label="Dismiss"
          className="-mr-1 shrink-0 rounded-sm p-0.5 text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <X className="size-4" />
        </button>
      )}
    </div>
  );
}

export { BannerCallout, BannerInline };
export type { BannerStatus };

